# Spec 133: mesothelioma lines scored by the scS-score (mean log2 TPM+1 of the top 20 cNMF20 genes, as in bulk_analysis.R) and viability after TF KO (DepMap 24Q4 Chronos gene effect)
#   A  the 21 mesothelioma lines ranked by scS-score, coloured by histology; median split into scS-low and scS-high
#   B  per TF (chromVAR TFs): gene effect scS-high minus scS-low (difference of medians) vs Spearman correlation with the score; the 68 selected TFs highlighted
#   C  gene effect of the TFs most associated with the score, lines ordered by scS-score
#   D  gene effect vs scS-score for the top TFs in each direction
# needs: DepMap 24Q4 (DEPMAP_DIR; OmicsExpressionProteinCodingGenesTPMLogp1.csv), ARCHR_DIR, SCRNA_DIR (cnmf_genelist_25_nfeat_5000.rds)
# outputs: spec133_scS_score_lines.csv, spec133_TF_vs_scS.csv, fig49_depmap_scS_score_TFs.{png,pdf}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R")); options(width = 220)
DM <- Sys.getenv("DEPMAP_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/Public_data/DepMap_24Q4"); AR <- Sys.getenv("ARCHR_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/mesothelioma/scATAC_PM/tumor_compartment/scatac_ArchR"); SR <- Sys.getenv("SCRNA_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/mesothelioma/scATAC_PM/tumor_compartment/scrna")
fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 1), formatC(p, format = "g", digits = 2))); SC <- "#eb6834"; N_SCS <- as.integer(Sys.getenv("N_SCS", "20"))
sel <- readRDS(file.path(AR, "selected_TF.rds")); suppressPackageStartupMessages(library(S4Vectors)); allTF <- union(unique(as.character(readRDS(file.path(AR, "TF_activators_genescore.rds"))$GeneScoreMatrix_name)), sel); SCREEN <- c("TCF3", "TEAD4", "TWIST1", "PITX1", "SOX9", "TEAD2", "BPTF", "HMGA1", "MEF2A", "MEF2D")
rdm <- function(f, genes) { hd <- strsplit(readLines(file.path(DM, f), n = 1), ",")[[1]]; sym <- sub(" \\(.*", "", hd); g <- intersect(genes, sym); x <- data.table::fread(file.path(DM, f), select = c(1, match(g, sym)), data.table = FALSE); M <- as.matrix(x[, -1]); dimnames(M) <- list(x[[1]], g); M }
GE <- rdm("CRISPRGeneEffect.csv", allTF); GD <- rdm("CRISPRGeneDependency.csv", allTF); mo <- read.csv(file.path(DM, "Model.csv"), stringsAsFactors = FALSE); mo <- mo[match(rownames(GE), mo$ModelID), ]; is_m <- grepl("esotheli", paste(mo$OncotreePrimaryDisease, mo$OncotreeSubtype))
sg <- head(readRDS(file.path(SR, "cnmf_genelist_25_nfeat_5000.rds"))[["cNMF20"]], N_SCS); EX <- rdm("OmicsExpressionProteinCodingGenesTPMLogp1.csv", sg); cat(sprintf("scS-score genes: %d of %d found in DepMap expression (missing: %s)\n", ncol(EX), length(sg), paste(setdiff(sg, colnames(EX)), collapse = ", ")))
ids <- rownames(GE)[is_m]; cat(sprintf("mesothelioma lines with CRISPR screen: %d; with expression: %d\n", length(ids), sum(ids %in% rownames(EX)))); ids <- intersect(ids, rownames(EX)); mm <- mo[match(ids, mo$ModelID), ]
L <- data.frame(ModelID = ids, line = mm$StrippedCellLineName, subtype = sub("Pleural Mesothelioma, | Type", "", gsub(" Type", "", mm$OncotreeSubtype)), scS = rowMeans(EX[ids, ]), stringsAsFactors = FALSE); L <- L[order(L$scS), ]; L$group <- ifelse(L$scS > median(L$scS), "scS-high", "scS-low"); write.csv(L, file.path(OUT, "spec133_scS_score_lines.csv"), row.names = FALSE); print(L[, -1], digits = 3, row.names = FALSE)
kw <- kruskal.test(L$scS, L$subtype); cat(sprintf("scS-score by histology: Kruskal p %s; medians %s\n", fp(kw$p.value), paste(sprintf("%s %.2f (n=%d)", names(tapply(L$scS, L$subtype, median)), tapply(L$scS, L$subtype, median), table(L$subtype)), collapse = "; ")))
E <- GE[L$ModelID, ]; rownames(E) <- L$line; P <- GD[L$ModelID, ]; hi <- L$group == "scS-high"; E <- E[, colSums(!is.na(E)) >= 15]
R <- do.call(rbind, lapply(colnames(E), function(k) { ct <- suppressWarnings(cor.test(E[, k], L$scS, method = "spearman")); data.frame(TF = k, selected = k %in% sel, screen = k %in% SCREEN, meso_median = median(E[, k], na.rm = TRUE), high_median = median(E[hi, k], na.rm = TRUE), low_median = median(E[!hi, k], na.rm = TRUE), diff = median(E[hi, k], na.rm = TRUE) - median(E[!hi, k], na.rm = TRUE), p_group = suppressWarnings(wilcox.test(E[hi, k], E[!hi, k])$p.value), rho = unname(ct$estimate), p_rho = ct$p.value, dep_high = sum(P[hi, k] > 0.5, na.rm = TRUE), dep_low = sum(P[!hi, k] > 0.5, na.rm = TRUE), stringsAsFactors = FALSE) }))
R$fdr_rho <- p.adjust(R$p_rho, "BH"); R$fdr_rho_selected <- NA; R$fdr_rho_selected[R$selected] <- p.adjust(R$p_rho[R$selected], "BH"); R <- R[order(R$p_rho), ]; write.csv(R, file.path(OUT, "spec133_TF_vs_scS.csv"), row.names = FALSE)
cat(sprintf("\n%d TFs tested, %d lines (%d scS-high, %d scS-low); p < 0.05 for the correlation: %d (expected by chance %.0f); minimum FDR %.2f\n", nrow(R), nrow(L), sum(hi), sum(!hi), sum(R$p_rho < 0.05), 0.05 * nrow(R), min(R$fdr_rho)))
sh <- c("TF", "selected", "meso_median", "high_median", "low_median", "diff", "p_group", "rho", "p_rho", "fdr_rho", "dep_high", "dep_low"); cat("\nmore required in scS-high lines (rho < 0), top 12:\n"); print(head(R[R$rho < 0, sh], 12), digits = 2, row.names = FALSE); cat("\nmore required in scS-low lines (rho > 0), top 12:\n"); print(head(R[R$rho > 0, sh], 12), digits = 2, row.names = FALSE)
cat("\nthe 68 selected TFs, top 12 by correlation p:\n"); print(head(R[R$selected, c(sh, "fdr_rho_selected")], 12), digits = 2, row.names = FALSE); cat("\nscreen TFs and TEAD/YAP axis:\n"); print(R[R$TF %in% c(SCREEN, "TEAD1", "TEAD3"), sh], digits = 2, row.names = FALSE)
# effect size filter for display: a TF must matter in at least one group
big <- R[pmin(R$high_median, R$low_median) < -0.2 | R$dep_high + R$dep_low >= 3, ]; cat(sprintf("\nTFs with a real viability effect in either group (group median < -0.2 or >= 3 dependent lines): %d; of these p_rho < 0.05:\n", nrow(big))); print(big[big$p_rho < 0.05, sh], digits = 2, row.names = FALSE)
spread <- function(y, gap) { o <- order(y); v <- y[o]; for (i in seq_along(v)[-1]) if (v[i] - v[i - 1] < gap) v[i] <- v[i - 1] + gap; y[o] <- v; y }
topH <- head(big$TF[big$rho < 0], 8); topL <- head(big$TF[big$rho > 0], 8); SUBC <- c(Epithelioid = "#4f7cac", Biphasic = "#b79a3c", Sarcomatoid = "#b0413e"); sc_ <- SUBC[L$subtype]; sc_[is.na(sc_)] <- "grey60"
save_fig("fig49_depmap_scS_score_TFs", 12.5, 7.6, function() {
  layout(rbind(c(1, 2, 3, 3), c(1, 4, 5, 6)), widths = c(0.85, 1.15, 0.6, 0.6)); par(oma = c(0, 0, 2.6, 0.3), family = "sans", mgp = c(2, 0.6, 0), tcl = -0.3); ttl <- function(x, y) { mtext(x, side = 3, adj = 0, line = 1.3, font = 2, cex = 0.75); mtext(y, side = 3, adj = 0, line = 0.35, cex = 0.52, col = INK2) }
  par(mar = c(3.4, 5.6, 2.8, 0.8)); n <- nrow(L); bp <- barplot(L$scS, horiz = TRUE, col = sc_, border = NA, names.arg = L$line, las = 1, cex.names = 0.62, cex.axis = 0.7, xlab = "scS-score (mean log2 TPM+1, top 20 cNMF20 genes)", cex.lab = 0.72, xpd = FALSE, xlim = c(min(L$scS) - 0.4, max(L$scS) + 0.1)); abline(h = mean(bp[c(sum(!hi), sum(!hi) + 1)]), lty = 2, col = INK)
  text(par("usr")[2], bp[sum(!hi)] - 0.2, "scS-low", adj = c(1, 1), cex = 0.62, col = INK2); text(par("usr")[2], bp[sum(!hi) + 1] + 0.2, "scS-high", adj = c(1, 0), cex = 0.62, col = INK2); legend("bottomright", names(SUBC), fill = SUBC, border = NA, bty = "n", cex = 0.62, inset = c(0, 0.06)); ttl("A  mesothelioma lines by scS-score", sprintf("%d lines; median split; histology Kruskal p %s", n, fp(kw$p.value)))
  par(mar = c(3.4, 3.6, 2.8, 0.8)); col <- ifelse(R$selected, SC, adjustcolor("grey45", 0.45)); o <- order(R$selected); plot(R$rho[o], R$diff[o], pch = ifelse(R$selected[o], 21, 16), bg = SC, col = ifelse(R$selected[o], INK2, adjustcolor("grey45", 0.45)), cex = ifelse(R$selected[o], 0.95, 0.5), lwd = 0.6, bty = "n", las = 1, cex.axis = 0.7, cex.lab = 0.72, xlab = "Spearman rho: gene effect vs scS-score", ylab = "gene effect: scS-high - scS-low (medians)"); abline(h = 0, v = 0, col = GRID)
  lab <- R[R$TF %in% c(head(topH, 3), head(topL, 4)), ]; text(lab$rho, lab$diff, lab$TF, pos = ifelse(lab$rho < 0, 1, 3), cex = 0.55, xpd = NA, font = ifelse(lab$selected, 2, 1)); legend("topleft", c("68 selected TFs", "other chromVAR TFs"), pch = c(21, 16), pt.bg = SC, col = c(INK2, "grey45"), bty = "n", cex = 0.6); mtext("more required in scS-high", side = 1, adj = 0, line = 2.4, cex = 0.5, col = INK2); mtext("more required in scS-low", side = 1, adj = 1, line = 2.4, cex = 0.5, col = INK2)
  ttl("B  TF KO effect vs scS-score", sprintf("%d TFs; labelled = strongest among TFs with a viability effect; bold = selected; min FDR %.2f", nrow(R), min(R$fdr_rho)))
  tf <- c(topH, rev(topL)); M <- t(E[, tf]); par(mar = c(4.6, 4.6, 2.8, 3.2)); zl <- 1.2; pal <- colorRampPalette(c("#2166ac", "#f7f7f7", "#b2182b"))(101); Z <- pmax(pmin(M, zl), -zl); image(seq_len(ncol(M)), seq_len(nrow(M)), t(Z[nrow(M):1, ]), col = pal, zlim = c(-zl, zl), axes = FALSE, xlab = "", ylab = ""); axis(1, at = seq_len(ncol(M)), labels = colnames(M), las = 2, tick = FALSE, cex.axis = 0.55, line = 0); axis(2, at = nrow(M):1, labels = rownames(M), las = 1, tick = FALSE, cex.axis = 0.6, line = -0.6, font = 1)
  abline(v = sum(!hi) + 0.5, lwd = 1.2); abline(h = length(topL) + 0.5, lwd = 1.2); dp <- t(P[, tf]) > 0.5; w <- which(dp[nrow(M):1, , drop = FALSE], arr.ind = TRUE); points(w[, 2], w[, 1], pch = 16, cex = 0.35); rect(seq_len(ncol(M)) - 0.5, -0.05, seq_len(ncol(M)) + 0.5, 0.4, col = sc_, border = NA, xpd = NA)
  ys <- seq(1, nrow(M), length.out = 102); rect(ncol(M) + 1.2, ys[-102], ncol(M) + 1.8, ys[-1], col = pal, border = NA, xpd = NA); text(ncol(M) + 2, c(1, mean(ys), nrow(M)), c(-zl, 0, zl), adj = 0, cex = 0.55, xpd = NA); text(ncol(M) + 1.2, 0.2, "gene effect", adj = 0, cex = 0.5, xpd = NA)
  ttl("C  gene effect, lines ordered by scS-score (low to high)", "top rows: more required in scS-high; bottom rows: in scS-low; dot = dependency; bar = histology")
  sc1 <- function(k, lab) { par(mar = c(3.4, 3.4, 2.8, 0.6)); r <- R[R$TF == k, ]; plot(L$scS, E[, k], pch = 21, bg = sc_, col = INK2, cex = 1.1, lwd = 0.6, bty = "n", las = 1, cex.axis = 0.7, cex.lab = 0.72, xlab = "scS-score", ylab = sprintf("%s gene effect", k)); abline(h = c(0, -0.5), lty = c(1, 3), col = c(INK, MUTED), lwd = 0.7); abline(lm(E[, k] ~ L$scS), col = INK2, lwd = 1); ttl(sprintf("%s  %s", lab, k), sprintf("rho %.2f, p %s", r$rho, fp(r$p_rho))) }
  sc1(topH[1], "D"); sc1(topL[1], "E"); selH <- R$TF[R$selected & R$TF %in% big$TF][1]; sc1(if (selH %in% c(topH[1], topL[1])) R$TF[R$selected & R$TF %in% big$TF][2] else selH, "F")
  mtext("DepMap mesothelioma lines scored by the scS-score: which TF knock-outs depend on it", outer = TRUE, side = 3, adj = 0, line = 1.2, font = 2, cex = 0.95); mtext("DepMap Public 24Q4, Chronos gene effect (negative = impaired viability); scS-score from DepMap expression", outer = TRUE, side = 3, adj = 0, line = 0.2, cex = 0.58, col = INK2)
})
